import json
import re
import html
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
refs = json.loads(Path('reference-targets.json').read_text())
answers = []

def plain(x):
    return html.unescape(re.sub(r'<[^>]*>', '', x or ''))

def paras(x):
    return re.findall(r'<p>(.*?)</p>', x, re.S)

def addp(x, *texts):
    return x.strip() + '\n' + '\n'.join('<p>' + t + '</p>' for t in texts)

def replace(x, a, b):
    assert x.count(a) == 1, (a, x.count(a))
    return x.replace(a, b)

def effect(kind, measure_id, description, before, after, unit, population, transition, source_quote, proposed_quote, burdens='Aucune obligation de remplacement ni aucun prélèvement nouveau ; les obligations autonomes maintenues gardent leur champ.'):
    return dict(kind=kind, measure_id=measure_id, description=description, before=before, after=after, unit=unit,
                affected_population=population, conditions_and_transition=transition,
                replacement_or_new_burdens=burdens, source_quote=source_quote, proposed_quote=proposed_quote)

def output(i, xml, reason, review, classification, assessment, limitations, burdens, effects=None, benefit=None, removed=None, repeal=None):
    s = sources[i]
    a = {k: s[k] for k in ('code_id', 'source_id', 'source_sha256', 'number')}
    a.update(proposed_xml=xml, reason=reason, review_notes=review,
             status='retained_unchanged' if xml is None else 'rewrite_draft')
    if xml is None:
        a['classification'] = 'retained_necessary'
    a['substantive_impact'] = dict(version=1, classification=classification, assessment=assessment,
        scope_limitations=limitations, new_burdens_review=burdens, effects=effects or [])
    if benefit:
        a['benefit_review'] = benefit
    if removed:
        a.update(change_type='normative_reduction', reform_policy_id='editorial_direction_2026_10_19', removed_provisions=removed)
    if repeal:
        a.update(change_type='full_repeal', repeal_policy_id='editorial_direction_2026_10_19', repeal_scope=repeal)
    answers.append(a)
    return a

IS_ID = 'is-distribution-benefices'
IS_NOTE = ('Nouveaux renvois aux V et VI de l’article 219 et, le cas échéant, aux XI à XIII de l’article 209 : ces cibles ne font pas partie des cibles requises de reference-targets.json. Leurs propositions ont été consultées dans le corpus public local impots.json ; elles ne sont pas le droit en vigueur. Bascule commune : exercices ouverts à compter de l’entrée en vigueur de la loi proposée, et non date historique des notes. Taux normal du projet : 20 % du bénéfice avant IS distribué ; taux réduits, exonérations, compte protégé, déficits et crédits conservent leurs conditions, sans double emploi. Minimum international et régimes annuels distincts réservés. Aucun chiffrage de recettes ou d’autofinancement n’est déduit de cette coordination.')
